SELECT ml.*, CASE ml.status WHEN 'NEW' THEN '新建' WHEN 'PICKING' THEN '领料中' WHEN 'COMPLETED' THEN '完成' ELSE ml.status END as task_status_name, mt.plan_start_date, mt.plan_end_date, IFNULL(detail_stats.material_count, 0) as material_count, IFNULL(detail_stats.picked_material_count, 0) as picked_material_count, IFNULL(detail_stats.pending_material_count, 0) as pending_material_count FROM mes_material_list ml LEFT JOIN mes_task mt ON ml.task_id = mt.id LEFT JOIN ( SELECT material_list_id, COUNT(*) as material_count, SUM(CASE WHEN pick_status IN ('PICKED', 'COMPLETED') THEN 1 ELSE 0 END) as picked_material_count, SUM(CASE WHEN pick_status = 'PENDING' THEN 1 ELSE 0 END) as pending_material_count FROM mes_material_list_detail WHERE del_flag = '0' GROUP BY material_list_id ) detail_stats ON ml.id = detail_stats.material_list_id
ml.del_flag = '0'
AND ml.task_code LIKE CONCAT('%', #{query.taskCode}, '%')
AND ml.product_code LIKE CONCAT('%', #{query.productCode}, '%')
AND ml.product_name LIKE CONCAT('%', #{query.productName}, '%')
AND ml.status = #{query.status}
AND ml.create_time >= #{query.createTimeStart}
AND ml.create_time <= #{query.createTimeEnd}
AND ml.factory_code = #{query.factoryCode}
ORDER BY ml.create_time DESC

SELECT status, COUNT(*) as count FROM mes_material_list WHERE del_flag = '0'
AND factory_code = #{factoryCode}
GROUP BY status
